<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$pdo=Database::connection();$error='';$result=null;$ref='';$phone='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$ref=strtoupper(trim($_POST['reference_code']??''));$phone=preg_replace('/[^0-9+]/','',$_POST['phone']??'');if(strlen($ref)<5||strlen($phone)<8)$error='أدخل رقم الطلب ورقم الهاتف المسجل بشكل صحيح.';else{
$q=$pdo->prepare("SELECT b.reference_code,b.status,b.created_at,b.passengers_count,o.name_ar origin_name,d.name_ar destination_name,t.departure_at FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN trips t ON t.id=b.trip_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE b.reference_code=? AND c.phone=? LIMIT 1");$q->execute([$ref,$phone]);$r=$q->fetch();if($r){$result=['type'=>'حجز رحلة','reference'=>$r['reference_code'],'status'=>$r['status'],'detail'=>$r['origin_name'].' ← '.$r['destination_name'],'date'=>$r['departure_at'],'created'=>$r['created_at']];}
if(!$result){$q=$pdo->prepare("SELECT r.reference_code,r.status,r.created_at,r.expected_date,r.service_type,p.title FROM umrah_requests r JOIN customers c ON c.id=r.customer_id LEFT JOIN umrah_programs p ON p.id=r.program_id WHERE r.reference_code=? AND c.phone=? LIMIT 1");$q->execute([$ref,$phone]);$r=$q->fetch();if($r)$result=['type'=>'طلب عمرة','reference'=>$r['reference_code'],'status'=>$r['status'],'detail'=>$r['title']?:($r['service_type']?:'عمرة مخصصة'),'date'=>$r['expected_date'],'created'=>$r['created_at']];}
if(!$result){$q=$pdo->prepare("SELECT r.reference_code,r.status,r.created_at,s.title FROM service_requests r JOIN customers c ON c.id=r.customer_id JOIN services s ON s.id=r.service_id WHERE r.reference_code=? AND c.phone=? LIMIT 1");$q->execute([$ref,$phone]);$r=$q->fetch();if($r)$result=['type'=>'طلب خدمة','reference'=>$r['reference_code'],'status'=>$r['status'],'detail'=>$r['title'],'date'=>null,'created'=>$r['created_at']];}
if(!$result)$error='لم نعثر على طلب يطابق الرقم والهاتف. تحقق من البيانات أو تواصل مع الاستقبال.';
}}
$labels=['new'=>'جديد','reviewing'=>'قيد المراجعة','confirmed'=>'مؤكد','quoted'=>'تم إرسال عرض السعر','need_info'=>'يتطلب استكمال بيانات','completed'=>'مكتمل','rejected'=>'مرفوض','cancelled'=>'ملغي'];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تتبع طلبك | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"><style>.track{max-width:620px;margin:50px auto;padding:24px}.track-card{background:#fff;border:1px solid #e5eaf0;border-radius:14px;padding:22px;margin-top:20px}.track form{display:grid;gap:14px}.track input{width:100%;padding:12px;border:1px solid #dce3eb;border-radius:8px}.status{display:inline-block;background:#eaf3fa;color:#173652;border-radius:20px;padding:7px 12px;font-weight:700}</style></head><body><header class="site-header"><a class="brand" href="/"><span class="brand-mark">م</span><b>أصل المتصدر</b></a><a href="/">الرئيسية</a></header><main class="track"><span class="eyebrow">خدمة متابعة الطلبات</span><h1>تتبع طلبك</h1><p class="muted">أدخل رقم المرجع ورقم الهاتف المستخدم عند إرسال الطلب.</p><section class="track-card"><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><label>رقم الطلب<input name="reference_code" value="<?=e($ref)?>" placeholder="مثال: UMR-..." required></label><label>رقم الهاتف<input name="phone" value="<?=e($phone)?>" inputmode="tel" required></label><button class="btn btn-primary">عرض حالة الطلب</button></form></section><?php if($result):?><section class="track-card"><span class="eyebrow"><?=e($result['type'])?></span><h2><?=e($result['reference'])?></h2><p><span class="status"><?=e($labels[$result['status']]??$result['status'])?></span></p><p><b>التفاصيل:</b> <?=e($result['detail']??'—')?></p><?php if($result['date']):?><p><b>الموعد:</b> <?=e($result['date'])?></p><?php endif;?><p class="muted">تاريخ تقديم الطلب: <?=e($result['created'])?></p></section><?php endif;?></main></body></html>